declare(strict_types=1);

namespace NetFusion\Core\RuleEngine\Rete;

use NetFusion\Core\RuleEngine\Contracts\FactInterface;
use NetFusion\Core\RuleEngine\Contracts\RuleInterface;

class TerminalNode
{
    protected RuleInterface $rule;
    protected Agenda $agenda;
    /** @var array<string, Activation> Active activations generated by this terminal node */
    protected array $activeActivations = [];

    public function __construct(RuleInterface $rule, Agenda $agenda)
    {
        $this->rule = $rule;
        $this->agenda = $agenda;
    }

    public function getRule(): RuleInterface
    {
        return $this->rule;
    }

    public function getAgenda(): Agenda
    {
        return $this->agenda;
    }

    /**
     * @param array<FactInterface> $tuple
     */
    public function assertTuple(array $tuple): void
    {
        if (!$this->rule->isEnabled()) {
            return;
        }

        $activation = new Activation($this->rule, $tuple);
        $this->activeActivations[$activation->getId()] = $activation;
        $this->agenda->addActivation($activation);
    }

    /**
     * @param array<FactInterface> $tuple
     */
    public function retractTuple(array $tuple): void
    {
        $dummy = new Activation($this->rule, $tuple);
        $id = $dummy->getId();

        if (isset($this->activeActivations[$id])) {
            unset($this->activeActivations[$id]);
        }

        foreach ($tuple as $fact) {
            $this->agenda->removeActivationsForFact($fact);
        }
    }

    public function clear(): void
    {
        $this->activeActivations = [];
    }
}
